INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000001',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn basic Hindi greetings at A1","Use नमस्ते and common salutations","Understand formal and informal greeting contexts"],"explanation":{"intro":"Hindi greetings vocabulary covers the most essential salutations used every day in India at A1.","culturalNote":"नमस्ते और शुभकामनाएँ: Hindi greetings reflect cultural respect and context. नमस्ते (Namaste) is the most universal greeting — hands folded, slight bow — used across India and increasingly worldwide. It means ''I bow to the divine in you'' (Sanskrit: namas = bow, te = you). नमस्कार (Namaskar) is slightly more formal. शुभ प्रभात (Shubh Prabhat) = good morning (shubh = auspicious, prabhat = dawn). शुभ संध्या (Shubh Sandhya) = good evening (sandhya = evening). आप कैसे हैं? (Aap kaise hain?) = How are you? (formal — aap = you formal). तुम कैसे हो? (Tum kaise ho?) = How are you? (informal). मैं ठीक हूँ (Main theek hoon) = I am fine. Devanagari script: Hindi is written in Devanagari — each syllable has a consonant + inherent ''a'' vowel. नमस्ते = na-mas-te."},"examples":[{"hindi":"नमस्ते! मैं राम हूँ। आप कैसे हैं?","transliteration":"Namaste! Main Ram hoon. Aap kaise hain?","english":"Hello! I am Ram. How are you?"},{"hindi":"शुभ प्रभात। मैं ठीक हूँ, धन्यवाद।","transliteration":"Shubh Prabhat. Main theek hoon, dhanyavad.","english":"Good morning. I am fine, thank you."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can greet people in Hindi and ask how they are."}}',
'{"items":[{"word":"नमस्ते","translation":"hello/greetings","transliteration":"namaste","pronunciation":"na-MAS-teh","example":"नमस्ते!"},{"word":"शुभ प्रभात","translation":"good morning","transliteration":"shubh prabhat","pronunciation":"shubh pra-BHAT","example":"शुभ प्रभात!"},{"word":"आप कैसे हैं?","translation":"how are you? (formal)","transliteration":"aap kaise hain?","pronunciation":"aap KAY-se hain","example":"आप कैसे हैं?"},{"word":"मैं ठीक हूँ","translation":"I am fine","transliteration":"main theek hoon","pronunciation":"main THEEK hoon","example":"मैं ठीक हूँ।"},{"word":"धन्यवाद","translation":"thank you","transliteration":"dhanyavad","pronunciation":"dhan-ya-VAD","example":"धन्यवाद!"},{"word":"नमस्कार","translation":"greetings (formal)","transliteration":"namaskar","pronunciation":"na-mas-KAR","example":"नमस्कार!"}]}',
'{"title":"मैं X हूँ — I am X (हूँ = am, first person singular)","pattern":"मैं X हूँ = I am X. मैं = I (first person singular pronoun). हूँ = am (present tense of होना = to be — first person singular). X = noun, adjective, name. Word order: Subject + Complement + Verb (SOV — subject-object-verb — Hindi standard order).","explanation":"Hindi follows SOV word order — the verb goes at the end. मैं (main) = I. हूँ (hoon) = am (1st person singular of होना = to be). मैं राम हूँ = I am Ram (literally: I Ram am). मैं ठीक हूँ = I am fine (literally: I fine am). Compare: आप हैं (aap hain) = you are (formal — 2nd person formal); तुम हो (tum ho) = you are (informal); वह है (vah hai) = he/she is.","examples":[{"sentence":"मैं सीता हूँ।","transliteration":"Main Seeta hoon.","translation":"I am Seeta."},{"sentence":"मैं खुश हूँ।","transliteration":"Main khush hoon.","translation":"I am happy."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"नमस्ते means?","options":["hello/greetings","good morning","thank you","goodbye"],"correctAnswer":"hello/greetings"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Good morning. I am fine, thank you.","options":["शुभ प्रभात। मैं ठीक हूँ, धन्यवाद।","नमस्ते। मैं ठीक हूँ, धन्यवाद।","शुभ संध्या। मैं ठीक हूँ, धन्यवाद।","शुभ प्रभात। आप कैसे हैं, धन्यवाद।"],"correctAnswer":"शुभ प्रभात। मैं ठीक हूँ, धन्यवाद।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मैं ठीक ___, धन्यवाद।","options":["हूँ","हैं","हो","है"],"correctAnswer":"हूँ"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Hello! I am Ram. How are you?","wordBankItems":["नमस्ते","!","मैं","राम","हूँ","।","आप","कैसे","हैं","?"],"correctAnswer":"नमस्ते ! मैं राम हूँ । आप कैसे हैं ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"धन्यवाद means?","options":["thank you","hello","goodbye","sorry"],"correctAnswer":"thank you"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000002',1,'APPROVED','PUBLISHED',
'{"objectives":["Introduce yourself in Hindi at A1","Use मेरा नाम and मैं X हूँ","Say your name, origin and basic personal information"],"explanation":{"intro":"Self-introduction vocabulary covers name, age, origin and occupation — the essentials for meeting someone new in Hindi at A1.","culturalNote":"मैं हूँ — Self Introduction: In Indian culture, meeting someone for the first time involves respectful greetings and context-setting. Key phrases: मेरा नाम X है (Mera naam X hai = My name is X — naam = name, mera = my). मैं X से हूँ (Main X se hoon = I am from X — se = from). मैं X साल का/की हूँ (Main X saal ka/ki hoon = I am X years old — saal = year, ka = masculine, ki = feminine). मेरा काम X है (Mera kaam X hai = My work/job is X). Script note: Devanagari vowel marks (matras) modify consonants — ि (i sound), ी (ee sound), ु (u sound). मेरा = me-ra (matra ा on र). Common names: राम, कृष्ण (male), सीता, गीता, प्रिया (female). Cultural note: Indians often ask age directly — it''s not considered rude — and family relationships are important in introductions."},"examples":[{"hindi":"नमस्ते! मेरा नाम प्रिया है। मैं दिल्ली से हूँ। मैं विद्यार्थी हूँ।","transliteration":"Namaste! Mera naam Priya hai. Main Dilli se hoon. Main vidyarthi hoon.","english":"Hello! My name is Priya. I am from Delhi. I am a student."},{"hindi":"मेरा नाम राज है। मैं मुंबई से हूँ। मैं डॉक्टर हूँ।","transliteration":"Mera naam Raj hai. Main Mumbai se hoon. Main doctor hoon.","english":"My name is Raj. I am from Mumbai. I am a doctor."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can introduce myself in Hindi — name, origin and occupation."}}',
'{"items":[{"word":"मेरा नाम","translation":"my name","transliteration":"mera naam","pronunciation":"MEH-ra naam","example":"मेरा नाम राज है।"},{"word":"मैं X से हूँ","translation":"I am from X","transliteration":"main X se hoon","pronunciation":"main X se hoon","example":"मैं दिल्ली से हूँ।"},{"word":"विद्यार्थी","translation":"student","transliteration":"vidyarthi","pronunciation":"vid-YAR-thi","example":"मैं विद्यार्थी हूँ।"},{"word":"साल","translation":"year","transliteration":"saal","pronunciation":"saal","example":"बीस साल।"},{"word":"काम","translation":"work/job","transliteration":"kaam","pronunciation":"kaam","example":"मेरा काम X है।"},{"word":"से","translation":"from/by","transliteration":"se","pronunciation":"se","example":"दिल्ली से।"}]}',
'{"title":"मेरा/मेरी X है — My X is (possession: मेरा = my masc., मेरी = my fem.)","pattern":"मेरा X है = My X is (masculine X). मेरी X है = My X is (feminine X). मेरा = my (masculine — used before masculine nouns). मेरी = my (feminine — used before feminine nouns). है = is (3rd person singular of होना). Hindi adjectives and possessives agree in gender and number with the noun they modify.","explanation":"Possession in Hindi: मेरा (mera) = my, masculine. मेरी (meri) = my, feminine. The possessive agrees with the gender of the NOUN it modifies, not the speaker. नाम (naam) = name — masculine → मेरा नाम. माँ (maan) = mother — feminine → मेरी माँ. है (hai) = is (3rd person singular). मेरा नाम राज है = My name is Raj (naam is masculine). Gender must be learned with each noun — no rule like German -e/-er.","examples":[{"sentence":"मेरा घर बड़ा है।","transliteration":"Mera ghar bada hai.","translation":"My house is big."},{"sentence":"मेरी किताब नई है।","transliteration":"Meri kitaab nai hai.","translation":"My book is new."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"मेरा नाम means?","options":["my name","your name","his name","her name"],"correctAnswer":"my name"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Hello! My name is Priya. I am from Delhi. I am a student.","options":["नमस्ते! मेरा नाम प्रिया है। मैं दिल्ली से हूँ। मैं विद्यार्थी हूँ।","नमस्ते! मेरा नाम प्रिया है। मैं मुंबई से हूँ। मैं विद्यार्थी हूँ।","नमस्ते! मेरा नाम सीता है। मैं दिल्ली से हूँ। मैं विद्यार्थी हूँ।","नमस्कार! मेरा नाम प्रिया है। मैं दिल्ली से हूँ। मैं डॉक्टर हूँ।"],"correctAnswer":"नमस्ते! मेरा नाम प्रिया है। मैं दिल्ली से हूँ। मैं विद्यार्थी हूँ।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मेरा ___ राज है।","options":["नाम","काम","घर","साल"],"correctAnswer":"नाम"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My name is Raj. I am from Mumbai.","wordBankItems":["मेरा","नाम","राज","है","।","मैं","मुंबई","से","हूँ","।"],"correctAnswer":"मेरा नाम राज है । मैं मुंबई से हूँ ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"से means?","options":["from/by","to/for","with/and","in/at"],"correctAnswer":"from/by"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000003',1,'APPROVED','PUBLISHED',
'{"objectives":["Count from 1 to 10 in Hindi at A1","Learn Devanagari numerals","Use numbers in simple sentences"],"explanation":{"intro":"Numbers 1-10 vocabulary introduces counting in Hindi and the Devanagari numeral script at A1.","culturalNote":"संख्याएँ 1-10: Hindi number words: एक (ek=1), दो (do=2), तीन (teen=3), चार (char=4), पाँच (paanch=5), छह (chhah=6), सात (saat=7), आठ (aath=8), नौ (nau=9), दस (das=10). Devanagari numerals: १ २ ३ ४ ५ ६ ७ ८ ९ १०. Note: Hindi uses its own numeral system in traditional contexts, though Arabic numerals (1,2,3...) are also widely used. पाँच has the chandrabindu (ँ) — nasal vowel marker. Important: Hindi numbers have a base-10 system but unique words for 11-99 — no simple compound rule until 100 (सौ=100). Usage: एक किलो (ek kilo = one kilo), दो बजे (do baje = two o''clock), तीन रुपये (teen rupaye = three rupees). Counting on fingers: start with little finger in North India."},"examples":[{"hindi":"मेरे पास पाँच रुपये हैं।","transliteration":"Mere paas paanch rupaye hain.","english":"I have five rupees."},{"hindi":"दो बिल्लियाँ हैं।","transliteration":"Do billiyan hain.","english":"There are two cats."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can count from 1 to 10 in Hindi."}}',
'{"items":[{"word":"एक","translation":"one","transliteration":"ek","pronunciation":"ek","example":"एक किताब।"},{"word":"दो","translation":"two","transliteration":"do","pronunciation":"do","example":"दो किताबें।"},{"word":"तीन","translation":"three","transliteration":"teen","pronunciation":"teen","example":"तीन बच्चे।"},{"word":"चार","translation":"four","transliteration":"char","pronunciation":"char","example":"चार घर।"},{"word":"पाँच","translation":"five","transliteration":"paanch","pronunciation":"paanch","example":"पाँच रुपये।"},{"word":"दस","translation":"ten","transliteration":"das","pronunciation":"das","example":"दस मिनट।"}]}',
'{"title":"X हैं — there are X (plural existential with हैं)","pattern":"X हैं = there are X (हैं = are — plural/formal present of होना). For existence/presence: दो बिल्लियाँ हैं = there are two cats. Word order: Numeral + Noun (plural) + हैं. Plural nouns: बिल्ली → बिल्लियाँ (cat → cats — feminine plural adds याँ). किताब → किताबें (book → books — feminine plural adds ें).","explanation":"हैं (hain) = are — third person plural (or second person formal singular) of होना. X + हैं = X are / there are X. For counting: numeral + plural noun + हैं. Note: Hindi plurals vary by gender and noun ending. Masculine -a nouns: लड़का → लड़के. Feminine -ī nouns: लड़की → लड़कियाँ. Some nouns are invariant in plural.","examples":[{"sentence":"तीन आम हैं।","transliteration":"Teen aam hain.","translation":"There are three mangoes."},{"sentence":"सात दिन हैं।","transliteration":"Saat din hain.","translation":"There are seven days."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"पाँच means?","options":["five","four","six","seven"],"correctAnswer":"five"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have five rupees.","options":["मेरे पास पाँच रुपये हैं।","मेरे पास चार रुपये हैं।","मेरे पास दस रुपये हैं।","मेरे पास पाँच किताबें हैं।"],"correctAnswer":"मेरे पास पाँच रुपये हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"सात ___ हैं।","options":["दिन","बिल्ली","किताब","रुपया"],"correctAnswer":"दिन"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: There are two cats.","wordBankItems":["दो","बिल्लियाँ","हैं","।"],"correctAnswer":"दो बिल्लियाँ हैं ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"दस means?","options":["ten","nine","eight","six"],"correctAnswer":"ten"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000004',1,'APPROVED','PUBLISHED',
'{"objectives":["Name family members in Hindi at A1","Use possessive pronouns with family terms","Describe a simple family structure"],"explanation":{"intro":"Family vocabulary introduces the words for immediate family members and how to talk about them in Hindi at A1.","culturalNote":"परिवार — Family: Hindi has highly specific kinship terms — more precise than English. माँ (maan/maa) = mother. पिताजी (pitaji) = father (ji is respectful suffix). बड़ा भाई (bada bhai) = elder brother. छोटा भाई (chhota bhai) = younger brother — age distinction built into the word usage. दादा/दादी (dada/dadi) = paternal grandfather/grandmother. नाना/नानी (nana/nani) = maternal grandfather/grandmother. भाभी (bhabhi) = elder brother''s wife. देवर (devar) = husband''s younger brother. The family is central to Indian life — joint family systems (संयुक्त परिवार = sanyukt parivar) are still common. Children address elders respectfully — never by first name. परिवार (parivaar) itself = family (from Sanskrit parivara = entourage, household). Key cultural practice: touching feet of elders (पैर छूना = pair chhuna = to touch feet — as sign of respect)."},"examples":[{"hindi":"मेरे परिवार में माँ, पिताजी, एक भाई और एक बहन हैं।","transliteration":"Mere parivaar mein maa, pitaji, ek bhai aur ek bahan hain.","english":"In my family there are mother, father, one brother and one sister."},{"hindi":"मेरी दादी बहुत अच्छी हैं।","transliteration":"Meri daadi bahut acchi hain.","english":"My grandmother is very good/kind."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name family members in Hindi and describe a simple family."}}',
'{"items":[{"word":"माँ","translation":"mother","transliteration":"maa","pronunciation":"maa","example":"मेरी माँ।"},{"word":"पिताजी","translation":"father","transliteration":"pitaji","pronunciation":"pi-ta-JEE","example":"मेरे पिताजी।"},{"word":"भाई","translation":"brother","transliteration":"bhai","pronunciation":"bhai","example":"मेरे भाई।"},{"word":"बहन","translation":"sister","transliteration":"bahan","pronunciation":"ba-HAN","example":"मेरी बहन।"},{"word":"दादी","translation":"paternal grandmother","transliteration":"daadi","pronunciation":"daa-dee","example":"मेरी दादी।"},{"word":"परिवार","translation":"family","transliteration":"parivaar","pronunciation":"pa-ri-VAAR","example":"मेरा परिवार।"}]}',
'{"title":"मेरे परिवार में X हैं — In my family there is/are X (में = in/within)","pattern":"X में Y हैं = In X there are Y. में = in (postposition — follows the noun in Hindi — unlike prepositions in English). मेरे परिवार में = in my family (mein = in; parivaar = family; mere = my-oblique-case). Oblique case: मेरा (direct) → मेरे (oblique — before postpositions like में, के, को).","explanation":"में (mein) = in (postposition — follows the noun: घर में = in the house, परिवार में = in the family). Oblique case: Hindi nouns and pronouns change form before postpositions. मेरा → मेरे before postpositions (oblique). The basic rule: direct case for subjects; oblique case before postpositions. X में Y हैं = In X there are Y. Useful for describing contents/members: घर में तीन कमरे हैं = In the house there are three rooms.","examples":[{"sentence":"मेरे घर में तीन कमरे हैं।","transliteration":"Mere ghar mein teen kamre hain.","translation":"In my house there are three rooms."},{"sentence":"स्कूल में बच्चे हैं।","transliteration":"School mein bachche hain.","translation":"In the school there are children."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"पिताजी means?","options":["father","grandfather","uncle","brother"],"correctAnswer":"father"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In my family there are mother, father, one brother and one sister.","options":["मेरे परिवार में माँ, पिताजी, एक भाई और एक बहन हैं।","मेरे परिवार में दादा, दादी, एक भाई और एक बहन हैं।","मेरे परिवार में माँ, पिताजी, दो भाई और एक बहन हैं।","मेरे घर में माँ, पिताजी, एक भाई और एक बहन हैं।"],"correctAnswer":"मेरे परिवार में माँ, पिताजी, एक भाई और एक बहन हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मेरे घर ___ तीन कमरे हैं।","options":["में","पर","से","को"],"correctAnswer":"में"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My grandmother is very good.","wordBankItems":["मेरी","दादी","बहुत","अच्छी","हैं","।"],"correctAnswer":"मेरी दादी बहुत अच्छी हैं ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"परिवार means?","options":["family","house","village","city"],"correctAnswer":"family"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000005',1,'APPROVED','PUBLISHED',
'{"objectives":["Name colours in Hindi at A1","Use colour adjectives with nouns","Describe objects by colour"],"explanation":{"intro":"Colour vocabulary covers the basic colours and how to use them as adjectives before nouns in Hindi at A1.","culturalNote":"रंग — Colours: Hindi colours: लाल (laal=red), नीला (neela=blue), हरा (hara=green), पीला (peela=yellow), सफ़ेद (safed=white), काला (kala=black), नारंगी (narangi=orange), बैंगनी (baingani=purple), गुलाबी (gulaabi=pink). Cultural note: रंग (rang) = colour — also used metaphorically (ज़िंदगी के रंग = colours of life). Colours in Indian festivals: Holi (होली) — festival of colours — people throw coloured powder (गुलाल = gulal). Saree colours have cultural significance: red for weddings, white traditionally for mourning. Saffron, white and green are the national flag colours. Key: Hindi adjectives agree in gender and number with the noun: लाल is invariant; नीला → नीली (masc → fem); हरा → हरी (masc → fem). Some colours ending in -a change: नीला किताब ✗ → नीली किताब ✓ (because किताब = feminine)."},"examples":[{"hindi":"यह गाड़ी लाल है।","transliteration":"Yah gaadi lal hai.","english":"This car is red."},{"hindi":"मेरी नीली किताब कहाँ है?","transliteration":"Meri neeli kitaab kahaan hai?","english":"Where is my blue book?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name colours in Hindi and describe objects by colour."}}',
'{"items":[{"word":"लाल","translation":"red","transliteration":"laal","pronunciation":"laal","example":"लाल फूल।"},{"word":"नीला/नीली","translation":"blue (masc/fem)","transliteration":"neela/neeli","pronunciation":"NEE-la/NEE-lee","example":"नीला आकाश।"},{"word":"हरा/हरी","translation":"green (masc/fem)","transliteration":"hara/hari","pronunciation":"ha-RA/ha-REE","example":"हरी घास।"},{"word":"पीला/पीली","translation":"yellow (masc/fem)","transliteration":"peela/peeli","pronunciation":"PEE-la/PEE-lee","example":"पीला केला।"},{"word":"सफ़ेद","translation":"white","transliteration":"safed","pronunciation":"sa-FED","example":"सफ़ेद कपड़ा।"},{"word":"काला/काली","translation":"black (masc/fem)","transliteration":"kala/kali","pronunciation":"KA-la/KA-lee","example":"काला कुत्ता।"}]}',
'{"title":"यह X Y है — This X is Y (यह = this, demonstrative pronoun)","pattern":"यह X Y है = This X is Y. यह = this (demonstrative pronoun — near — singular). वह = that (demonstrative — far — singular). ये = these (near — plural). वे = those (far — plural). यह गाड़ी लाल है = This car is red. Adjective before noun when modifying; adjective after noun (predicate) with है/हैं.","explanation":"यह (yah/yeh) = this (near singular demonstrative pronoun/determiner). वह (woh) = that. Adjective position: (a) attributive: before noun — नीली किताब (blue book — adjective agrees); (b) predicate: after noun + verb — किताब नीली है (the book is blue). When attributive, adjectives agree in gender (and sometimes number) with the noun. लाल is invariant (does not change). नीला → नीली before feminine noun. हरा → हरे (before masculine plural). Example: नीला आकाश (blue sky — आकाश is masculine) vs. हरी घास (green grass — घास is feminine).","examples":[{"sentence":"यह फूल लाल है।","transliteration":"Yah phool lal hai.","translation":"This flower is red."},{"sentence":"वह बिल्ली काली है।","transliteration":"Vah billi kaali hai.","translation":"That cat is black."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"हरा means?","options":["green","yellow","blue","white"],"correctAnswer":"green"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"This car is red.","options":["यह गाड़ी लाल है।","यह गाड़ी नीली है।","वह गाड़ी लाल है।","यह किताब लाल है।"],"correctAnswer":"यह गाड़ी लाल है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मेरी ___ किताब कहाँ है?","options":["नीली","नीला","नीले","लाल"],"correctAnswer":"नीली"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: That cat is black.","wordBankItems":["वह","बिल्ली","काली","है","।"],"correctAnswer":"वह बिल्ली काली है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"सफ़ेद means?","options":["white","black","red","pink"],"correctAnswer":"white"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000006',1,'APPROVED','PUBLISHED',
'{"objectives":["Name common foods and drinks in Hindi at A1","Use मुझे X पसंद है to express food preferences","Order food or express hunger"],"explanation":{"intro":"Food and drink vocabulary covers common Indian foods, drinks, and how to express preferences and hunger at A1.","culturalNote":"खाना-पीना — Food and Drink: खाना (khaana) = food (also verb: to eat). पानी (paani) = water. चाय (chaay) = tea — India''s most iconic drink. दूध (doodh) = milk. रोटी (roti) = flatbread — staple in North India. चावल (chaawal) = rice — staple in South/East India. दाल (daal) = lentils — eaten across India daily. आम (aam) = mango — national fruit of India. मुझे भूख लगी है (Mujhe bhookh lagi hai) = I am hungry (literally: hunger has attached to me — different structure). मुझे X पसंद है (Mujhe X pasand hai) = I like X (literally: X is liked to me). Cultural note: India has incredible regional food diversity — a unified ''Indian cuisine'' is a simplification. Vegetarianism is widespread (30-40% vegetarian). Thali = a platter of multiple dishes. Street food culture: chaat, vada pav, pani puri."},"examples":[{"hindi":"मुझे चाय पसंद है।","transliteration":"Mujhe chaay pasand hai.","english":"I like tea."},{"hindi":"मुझे भूख लगी है। मैं रोटी खाना चाहता हूँ।","transliteration":"Mujhe bhookh lagi hai. Main roti khaana chahta hoon.","english":"I am hungry. I want to eat roti."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name common Indian foods and express food preferences in Hindi."}}',
'{"items":[{"word":"खाना","translation":"food / to eat","transliteration":"khaana","pronunciation":"KHAA-na","example":"खाना खाना।"},{"word":"चाय","translation":"tea","transliteration":"chaay","pronunciation":"chaay","example":"चाय पीना।"},{"word":"रोटी","translation":"flatbread/roti","transliteration":"roti","pronunciation":"ro-TEE","example":"रोटी खाना।"},{"word":"चावल","translation":"rice","transliteration":"chaawal","pronunciation":"CHAA-wal","example":"चावल पकाना।"},{"word":"पानी","translation":"water","transliteration":"paani","pronunciation":"PAA-nee","example":"पानी पीना।"},{"word":"भूख","translation":"hunger","transliteration":"bhookh","pronunciation":"bhookh","example":"भूख लगी है।"}]}',
'{"title":"मुझे X पसंद है — I like X (dative-like construction with मुझे)","pattern":"मुझे X पसंद है = I like X. मुझे = to me (oblique/dative form of मैं = I — mujhe is the dative). X = the thing liked (subject in Hindi structure). पसंद = liking (noun from Persian). है = is. Literally: ''To me X is liked/pleasing.'' This is a common Hindi construction where the experiencer goes in the dative (मुझे) and the thing experienced is the grammatical subject.","explanation":"Dative construction: Hindi frequently uses मुझे (to me), तुम्हें (to you informal), आपको (to you formal), उसे (to him/her) for experiences and sensations. मुझे X पसंद है = I like X. मुझे भूख लगी है = I am hungry (hunger has struck me). मुझे ठंड लगती है = I feel cold. The thing liked/felt is the grammatical subject in Hindi, not the experiencer. Compare with German ''mir gefällt es'' (it pleases me) — similar dative inversion.","examples":[{"sentence":"मुझे आम पसंद है।","transliteration":"Mujhe aam pasand hai.","translation":"I like mango."},{"sentence":"मुझे प्यास लगी है।","transliteration":"Mujhe pyaas lagi hai.","translation":"I am thirsty."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"चाय means?","options":["tea","water","milk","juice"],"correctAnswer":"tea"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I like tea.","options":["मुझे चाय पसंद है।","मुझे दूध पसंद है।","मुझे पानी पसंद है।","मुझे चाय पसंद नहीं है।"],"correctAnswer":"मुझे चाय पसंद है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मुझे ___ लगी है।","options":["भूख","खाना","चाय","रोटी"],"correctAnswer":"भूख"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I like mango.","wordBankItems":["मुझे","आम","पसंद","है","।"],"correctAnswer":"मुझे आम पसंद है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"रोटी means?","options":["flatbread","rice","lentils","mango"],"correctAnswer":"flatbread"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000007',1,'APPROVED','PUBLISHED',
'{"objectives":["Tell the time in Hindi at A1","Use बजे to express hours","Ask and answer what time it is"],"explanation":{"intro":"Time-telling vocabulary covers hours and the key phrase बजे (baje = o''clock) for telling time in Hindi at A1.","culturalNote":"समय — Time: कितने बजे हैं? (Kitne baje hain?) = What time is it? (literally: how many have struck/struck?). बजे (baje) = o''clock (from बजना = to ring/sound — the striking of a bell). एक बजे (ek baje) = one o''clock. दो बजे (do baje) = two o''clock. साढ़े तीन बजे (saadhe teen baje) = three thirty (saadhe = half past — used before whole numbers for X:30). पौने (paune) = quarter to: पौने चार = quarter to four. सवा (sawa) = quarter past: सवा दो = quarter past two. Cultural note: India has one time zone (IST = Indian Standard Time = UTC+5:30 — the only :30 offset in common use). Indian Standard Time was designed to be equidistant from the eastern and western extremes of India. AM = सुबह (subah = morning), PM = शाम (shaam = evening) or रात (raat = night). Example: सुबह दस बजे = ten in the morning."},"examples":[{"hindi":"अभी तीन बजे हैं।","transliteration":"Abhi teen baje hain.","english":"It is three o''clock now."},{"hindi":"मैं सुबह सात बजे उठता हूँ।","transliteration":"Main subah saat baje uthta hoon.","english":"I wake up at seven in the morning."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can tell the time in Hindi and say what time I do things."}}',
'{"items":[{"word":"बजे","translation":"o''clock","transliteration":"baje","pronunciation":"BA-je","example":"तीन बजे।"},{"word":"कितने बजे हैं?","translation":"what time is it?","transliteration":"kitne baje hain?","pronunciation":"KIT-ne BA-je hain","example":"कितने बजे हैं?"},{"word":"अभी","translation":"now","transliteration":"abhi","pronunciation":"ab-HEE","example":"अभी क्या समय है?"},{"word":"सुबह","translation":"morning","transliteration":"subah","pronunciation":"su-BAH","example":"सुबह सात बजे।"},{"word":"शाम","translation":"evening","transliteration":"shaam","pronunciation":"shaam","example":"शाम छह बजे।"},{"word":"उठना","translation":"to wake up/rise","transliteration":"uthna","pronunciation":"UTH-na","example":"सुबह उठना।"}]}',
'{"title":"X बजे Y करना — to do Y at X o''clock (बजे = at X o''clock, time postposition pattern)","pattern":"X बजे Y करना = to do Y at X o''clock. बजे after a number = at X o''clock. सुबह X बजे = at X o''clock in the morning. Pattern: Time word (morning/evening) + number + बजे + action. Example: मैं सुबह सात बजे उठता हूँ = I wake up at seven in the morning.","explanation":"बजे (baje) = at X o''clock (postposition following a number). Used for scheduled times: दो बजे = at two o''clock (not ''two strokes'' — functions as a time postposition). सुबह (subah) = morning. शाम (shaam) = evening. रात (raat) = night. Verb form: उठता हूँ (present habitual masculine — main uthta hoon = I wake up usually). Note: उठना = to get up/wake. Habitual present: consonant verb stem + ता/ती/ते + हूँ/हैं/हो. Main uthta hoon (I, masculine). Main uthti hoon (I, feminine).","examples":[{"sentence":"वह शाम पाँच बजे घर आता है।","transliteration":"Vah shaam paanch baje ghar aata hai.","translation":"He comes home at five in the evening."},{"sentence":"हम दोपहर एक बजे खाना खाते हैं।","transliteration":"Hum dopahar ek baje khaana khaate hain.","translation":"We eat lunch at one in the afternoon."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"बजे means?","options":["o''clock","minute","hour","time"],"correctAnswer":"o''clock"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"It is three o''clock now.","options":["अभी तीन बजे हैं।","अभी चार बजे हैं।","अभी तीन बजे है।","अभी तीन मिनट हैं।"],"correctAnswer":"अभी तीन बजे हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मैं सुबह सात ___ उठता हूँ।","options":["बजे","मिनट","घंटे","समय"],"correctAnswer":"बजे"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He comes home at five in the evening.","wordBankItems":["वह","शाम","पाँच","बजे","घर","आता","है","।"],"correctAnswer":"वह शाम पाँच बजे घर आता है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"सुबह means?","options":["morning","evening","night","afternoon"],"correctAnswer":"morning"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000008',1,'APPROVED','PUBLISHED',
'{"objectives":["Name days of the week in Hindi at A1","Use आज, कल, परसों for today, tomorrow, day after tomorrow","Talk about weekly schedules"],"explanation":{"intro":"Days and week vocabulary covers the seven days, key time adverbs, and simple schedule sentences in Hindi at A1.","culturalNote":"दिन और सप्ताह — Days and Week: Hindi days of the week are named after celestial bodies: सोमवार (Somvaar = Monday — Som = Moon/Soma), मंगलवार (Mangalvaar = Tuesday — Mangal = Mars), बुधवार (Budhvaar = Wednesday — Budh = Mercury), गुरुवार/बृहस्पतिवार (Guruvaar = Thursday — Guru = Jupiter), शुक्रवार (Shukvaar = Friday — Shukra = Venus), शनिवार (Shanivaar = Saturday — Shani = Saturn), रविवार (Ravivaar = Sunday — Ravi = Sun). All days end in -वार (vaar = day — Sanskrit vara). Cultural note: सप्ताह (saptaah) = week (sapta = seven — Sanskrit). आज (aaj) = today. कल (kal) = tomorrow OR yesterday (context determines). परसों (parson) = day after tomorrow OR day before yesterday. नरसों (narson) = three days from now/ago. This bidirectional use of कल is unique — context always clarifies."},"examples":[{"hindi":"आज सोमवार है।","transliteration":"Aaj Somvaar hai.","english":"Today is Monday."},{"hindi":"कल मेरी परीक्षा है।","transliteration":"Kal meri pariksha hai.","english":"Tomorrow is my exam."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name the days of the week in Hindi and use today/tomorrow/yesterday."}}',
'{"items":[{"word":"सोमवार","translation":"Monday","transliteration":"somvaar","pronunciation":"SOM-vaar","example":"सोमवार को।"},{"word":"शुक्रवार","translation":"Friday","transliteration":"shukvaar","pronunciation":"SHUK-vaar","example":"शुक्रवार को।"},{"word":"रविवार","translation":"Sunday","transliteration":"ravivaar","pronunciation":"ra-vi-VAAR","example":"रविवार को।"},{"word":"आज","translation":"today","transliteration":"aaj","pronunciation":"aaj","example":"आज क्या है?"},{"word":"कल","translation":"tomorrow/yesterday","transliteration":"kal","pronunciation":"kal","example":"कल मिलेंगे।"},{"word":"सप्ताह","translation":"week","transliteration":"saptaah","pronunciation":"sap-TAAH","example":"इस सप्ताह।"}]}',
'{"title":"X को Y होता/होती है — On X, Y happens (को for days of the week)","pattern":"Day + को = on (day). X को Y होता है = On X, Y happens (habitual). को after day names marks ''on that day.'' Example: सोमवार को स्कूल होता है = On Monday there is school. रविवार को छुट्टी होती है = On Sunday there is a holiday.","explanation":"को (ko) after day names = ''on (day of week)'' — the day postposition. Habitual/routine present: होता है (hota hai — masculine habitual) or होती है (hoti hai — feminine habitual). Different from है alone (which is a simple present state). होना (hona) = to be; habitual form: होता/होती/होते + है/हैं. Example: रविवार को मैं घर पर रहता हूँ = On Sundays I stay at home. Note: को is also used for indirect objects and several other functions — context distinguishes.","examples":[{"sentence":"शनिवार को बाज़ार होता है।","transliteration":"Shanivaar ko baazaar hota hai.","translation":"On Saturday the market takes place."},{"sentence":"गुरुवार को योग की क्लास होती है।","transliteration":"Guruvaar ko yog ki class hoti hai.","translation":"On Thursday there is a yoga class."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"रविवार means?","options":["Sunday","Saturday","Monday","Friday"],"correctAnswer":"Sunday"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Today is Monday.","options":["आज सोमवार है।","कल सोमवार है।","आज मंगलवार है।","आज सोमवार था।"],"correctAnswer":"आज सोमवार है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"कल मेरी ___ है।","options":["परीक्षा","दिन","सप्ताह","समय"],"correctAnswer":"परीक्षा"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: On Saturday the market takes place.","wordBankItems":["शनिवार","को","बाज़ार","होता","है","।"],"correctAnswer":"शनिवार को बाज़ार होता है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"कल means?","options":["tomorrow/yesterday","today","now","later"],"correctAnswer":"tomorrow/yesterday"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000009',1,'APPROVED','PUBLISHED',
'{"objectives":["Name rooms and parts of a house in Hindi at A1","Use कहाँ है? to ask where something is","Describe a simple house using में"],"explanation":{"intro":"House and rooms vocabulary covers key parts of the home and how to locate things using कहाँ है? (Where is?) in Hindi at A1.","culturalNote":"घर और कमरे — House and Rooms: घर (ghar) = house/home. कमरा (kamra) = room (masculine — कमरे plural). रसोई (rasoi) = kitchen. बाथरूम (bathroom) / शौचालय (shauchalaya) = bathroom/toilet. बैठक/बैठकखाना (baithak) = sitting room/living room. शयनकक्ष (shayanakaksha) / सोने का कमरा (sone ka kamra) = bedroom (sone = sleeping). छत (chhat) = roof/terrace — important in India, used for sleeping in summer, drying clothes. आँगन (aangan) = courtyard — traditional Indian homes center around a courtyard. Cultural note: Indian homes traditionally have a पूजा घर (pooja ghar = prayer room/altar) — a dedicated space for worship. संयुक्त परिवार (sanyukt parivaar = joint family) homes are larger multi-generational spaces. महल (mahal) = palace. झोपड़ी (jhopdi) = hut. कहाँ है? (kahaan hai?) = where is?"},"examples":[{"hindi":"रसोई घर के पीछे है।","transliteration":"Rasoi ghar ke peeche hai.","english":"The kitchen is behind the house."},{"hindi":"किताब कहाँ है? वह मेज़ पर है।","transliteration":"Kitaab kahaan hai? Vah mez par hai.","english":"Where is the book? It is on the table."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name rooms of a house in Hindi and ask/answer where things are."}}',
'{"items":[{"word":"घर","translation":"house/home","transliteration":"ghar","pronunciation":"ghar","example":"मेरा घर।"},{"word":"कमरा","translation":"room","transliteration":"kamra","pronunciation":"KAM-ra","example":"तीन कमरे।"},{"word":"रसोई","translation":"kitchen","transliteration":"rasoi","pronunciation":"ra-SOY","example":"रसोई में।"},{"word":"कहाँ है?","translation":"where is?","transliteration":"kahaan hai?","pronunciation":"ka-HAAN hai","example":"किताब कहाँ है?"},{"word":"मेज़","translation":"table","transliteration":"mez","pronunciation":"mez","example":"मेज़ पर।"},{"word":"पर","translation":"on/at","transliteration":"par","pronunciation":"par","example":"मेज़ पर किताब।"}]}',
'{"title":"X कहाँ है? — Where is X? (कहाँ = where, question word at end)","pattern":"X कहाँ है? = Where is X? कहाँ = where (question word). है = is. In Hindi, question words typically stay in the same position as the answer would be — SOV word order is maintained. Answer: X Y पर है = X is on Y. Postpositions of place: पर = on/at; में = in; के पास = near; के ऊपर = above; के नीचे = below; के पीछे = behind; के आगे = in front of.","explanation":"कहाँ (kahaan) = where. Question formation in Hindi: replace the unknown with a question word — same position as the answer. X कहाँ है? = Where is X? (X at subject position, कहाँ where the location would be). Postpositions of place: पर (par) = on/at; में (mein) = in; के पास (ke paas) = near/with; के सामने (ke saamne) = in front of; के पीछे (ke peeche) = behind. Example: किताब मेज़ पर है = The book is on the table.","examples":[{"sentence":"चाबी कहाँ है? चाबी दराज़ में है।","transliteration":"Chaabi kahaan hai? Chaabi daraaz mein hai.","translation":"Where is the key? The key is in the drawer."},{"sentence":"बच्चे कहाँ हैं? वे बगीचे में हैं।","transliteration":"Bachche kahaan hain? Ve bageeche mein hain.","translation":"Where are the children? They are in the garden."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"रसोई means?","options":["kitchen","bedroom","bathroom","living room"],"correctAnswer":"kitchen"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Where is the book? It is on the table.","options":["किताब कहाँ है? वह मेज़ पर है।","किताब कहाँ है? वह कमरे में है।","किताब कहाँ है? वह कुर्सी पर है।","किताब क्या है? वह मेज़ पर है।"],"correctAnswer":"किताब कहाँ है? वह मेज़ पर है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"चाबी दराज़ ___ है।","options":["में","पर","से","को"],"correctAnswer":"में"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Where are the children? They are in the garden.","wordBankItems":["बच्चे","कहाँ","हैं","?","वे","बगीचे","में","हैं","।"],"correctAnswer":"बच्चे कहाँ हैं ? वे बगीचे में हैं ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"पर means?","options":["on/at","in","from","to"],"correctAnswer":"on/at"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000000a',1,'APPROVED','PUBLISHED',
'{"objectives":["Name body parts in Hindi at A1","Use मेरा/मेरी with body parts","Describe simple physical conditions"],"explanation":{"intro":"Body parts vocabulary covers the main parts of the human body and how to talk about them in Hindi at A1.","culturalNote":"शरीर के अंग — Body Parts: शरीर (shareer) = body (Sanskrit). सिर (sir) = head. आँख (aankh) = eye. कान (kaan) = ear. नाक (naak) = nose. मुँह (munh) = mouth. हाथ (haath) = hand/arm. पाँव/पैर (paanv/pair) = foot/leg. पेट (pet) = stomach. पीठ (peeth) = back. Cultural note: शरीर in Indian philosophy is one of the five sheaths (पञ्चकोश = pancha kosha) of the self in Vedanta — the physical body (अन्नमय कोश = annamaya kosha = food-made sheath). Medical terms: Ayurveda (आयुर्वेद = science of life) uses body part terminology extensively. Pointing at someone with your finger is considered rude in Indian culture — use an open hand gesture instead. Common expressions: हाथ बँटाना (haath bantana = to lend a hand = to help). सिर दर्द (sir dard = headache — sir = head, dard = pain). मुझे X में दर्द है (Mujhe X mein dard hai = I have pain in X)."},"examples":[{"hindi":"मेरे दो हाथ और दो पाँव हैं।","transliteration":"Mere do haath aur do paanv hain.","english":"I have two hands and two feet."},{"hindi":"मुझे सिर दर्द है।","transliteration":"Mujhe sir dard hai.","english":"I have a headache."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name body parts in Hindi and describe simple physical conditions."}}',
'{"items":[{"word":"सिर","translation":"head","transliteration":"sir","pronunciation":"sir","example":"मेरा सिर।"},{"word":"आँख","translation":"eye","transliteration":"aankh","pronunciation":"aankh","example":"मेरी आँखें।"},{"word":"हाथ","translation":"hand/arm","transliteration":"haath","pronunciation":"haath","example":"मेरे हाथ।"},{"word":"पाँव/पैर","translation":"foot/leg","transliteration":"paanv/pair","pronunciation":"paanv/pair","example":"मेरे पाँव।"},{"word":"पेट","translation":"stomach","transliteration":"pet","pronunciation":"pet","example":"पेट दर्द।"},{"word":"दर्द","translation":"pain","transliteration":"dard","pronunciation":"dard","example":"दर्द होना।"}]}',
'{"title":"मुझे X में दर्द है — I have pain in X (मुझे + location + दर्द है)","pattern":"मुझे X में दर्द है = I have pain in X. मुझे = to me (dative — experiencer). X में = in X (location of pain). दर्द = pain (noun). है = is. Pattern: Experiencer (dative) + location + दर्द है. Compare: मुझे बुखार है (Mujhe bukhar hai = I have a fever — no location needed). This dative-experiencer construction appears throughout Hindi for physical and emotional states.","explanation":"दर्द (dard) = pain. मुझे (mujhe) = to me/I (dative — used for experiences that ''happen to'' the person). मुझे X में दर्द है = I have pain in X (literally: to me in X pain is). Body location in dative construction: सिर में दर्द = pain in the head (headache); पेट में दर्द = stomach pain; पीठ में दर्द = back pain. Contrast: मेरे हाथ में दर्द है (mere haath mein dard hai = there is pain in my hand — using मेरे + में instead of मुझे). Both constructions are used.","examples":[{"sentence":"मुझे पेट में दर्द है।","transliteration":"Mujhe pet mein dard hai.","translation":"I have a stomach ache."},{"sentence":"उसे पीठ में दर्द है।","transliteration":"Use peeth mein dard hai.","translation":"She/he has back pain."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"हाथ means?","options":["hand/arm","foot","head","eye"],"correctAnswer":"hand/arm"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have two hands and two feet.","options":["मेरे दो हाथ और दो पाँव हैं।","मेरे एक हाथ और दो पाँव हैं।","मेरे दो हाथ और दो आँखें हैं।","मेरे दो पाँव और दो पाँव हैं।"],"correctAnswer":"मेरे दो हाथ और दो पाँव हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मुझे ___ में दर्द है।","options":["पेट","भूख","चाय","घर"],"correctAnswer":"पेट"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I have a headache.","wordBankItems":["मुझे","सिर","दर्द","है","।"],"correctAnswer":"मुझे सिर दर्द है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"दर्द means?","options":["pain","illness","ache","fever"],"correctAnswer":"pain"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

